42	        // This list mirrors OwnerFieldsDto's required fields by hand: it must track the schema's
43	        // `required` set. We check presence/non-blankness only, a narrower rule than the DTO's full
44	        // constraints (@Size/@Pattern), so bean validation is intentionally not used here.
45	        // Normalize the address first so the required-field check rejects an address that is blank
46	        // after normalization (e.g. "   "), and so downstream steps store/return and compare the
47	        // canonical form. OwnerAddress.normalize yields "" for a null or all-whitespace address.
48	        String normalizedAddress = OwnerAddress.normalize(request.getAddress());
49	        request.setAddress(normalizedAddress);
50	
51	        List<String> missing = new ArrayList<>();
52	        require(missing, "firstName", request.getFirstName());
53	        require(missing, "lastName", request.getLastName());
54	        require(missing, "address", normalizedAddress);
55	        require(missing, "city", request.getCity());
56	        require(missing, "telephone", request.getTelephone());
