62	        // persist it and the response echoes the E.164 form.
63	        String e164 = OwnerTelephone.toE164(request.getTelephone());
64	        if (e164 == null) {
65	            throw new InvalidTelephoneException(request.getTelephone());
66	        }
67	        request.setTelephone(e164);
68	
69	        // Email is optional: only an email that is present (non-blank) must be a valid address. A valid
70	        // value is lower-cased and written back (like telephone above) so downstream steps store and
71	        // return the canonical form.
72	        String email = request.getEmail();
