27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "postcode")
47	    private String postcode;
48	
49	    @Column(name = "telephone")
50	    @NotEmpty
51	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ then 8 to 15 digits)")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    private String email;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "membership_number")
67	    private String membershipNumber;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Transient
76	    private Boolean bulkSignupWarning;
77	
78	    @Transient
79	    private Boolean possibleDuplicate;
80	
81	    @Transient
82	    private Integer possibleDuplicateOf;
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getPostcode() {
104	        return this.postcode;
105	    }
106	
107	    public void setPostcode(String postcode) {
108	        this.postcode = postcode;
109	    }
110	
111	    public String getTelephone() {
112	        return this.telephone;
113	    }
114	
115	    public void setTelephone(String telephone) {
116	        this.telephone = telephone;
117	    }
118	
119	    /**
120	     * The stored {@link #getTelephone() telephone} formatted for humans by {@link TelephoneFormatter}:
121	     * the country code, a space, then the national digits grouped in threes (e.g. {@code +61412345678}
122	     * -> {@code +61 412 345 678}). The raw {@link #getTelephone() telephone} stays in E.164 form.
123	     */
124	    public String getTelephoneDisplay() {
125	        return TelephoneFormatter.toDisplay(this.telephone);
126	    }
127	
128	    public String getEmail() {
129	        return this.email;
130	    }
131	
132	    public void setEmail(String email) {
133	        this.email = email;
134	    }
135	
136	    public LocalDate getRegistrationDate() {
137	        return this.registrationDate;
138	    }
139	
140	    public void setRegistrationDate(LocalDate registrationDate) {
141	        this.registrationDate = registrationDate;
142	    }
143	
144	    public LocalDate getBirthDate() {
145	        return this.birthDate;
146	    }
147	
148	    public void setBirthDate(LocalDate birthDate) {
149	        this.birthDate = birthDate;
150	    }
151	
152	    /**
153	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
154	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
155	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
156	     * (so the field is absent from the response) or the registration date is unknown.
157	     */
158	    public String getAgeBand() {
159	        if (this.birthDate == null || this.registrationDate == null) {
160	            return null;
161	        }
162	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
163	        if (age < 18) {
164	            return "MINOR";
165	        }
166	        if (age < 65) {
167	            return "ADULT";
168	        }
169	        return "SENIOR";
170	    }
171	
172	    public String getCustomerCode() {
173	        return this.customerCode;
174	    }
175	
176	    public void setCustomerCode(String customerCode) {
177	        this.customerCode = customerCode;
178	    }
179	
180	    public String getMembershipNumber() {
181	        return this.membershipNumber;
182	    }
183	
184	    public void setMembershipNumber(String membershipNumber) {
185	        this.membershipNumber = membershipNumber;
186	    }
187	
188	    public String getHouseholdId() {
189	        return this.householdId;
190	    }
191	
192	    public void setHouseholdId(String householdId) {
193	        this.householdId = householdId;
194	    }
195	
196	    public Integer getNamesakeCount() {
197	        return this.namesakeCount;
198	    }
199	
200	    public void setNamesakeCount(Integer namesakeCount) {
201	        this.namesakeCount = namesakeCount;
202	    }
203	
204	    /**
205	     * Whether this response should carry a bulk-signup warning: {@code true} when more than 80 owners
206	     * have already been created for this owner's registration day. Computed per request, not persisted.
207	     */
208	    public Boolean getBulkSignupWarning() {
209	        return this.bulkSignupWarning;
210	    }
211	
212	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
213	        this.bulkSignupWarning = bulkSignupWarning;
214	    }
215	
216	    /**
217	     * Whether this owner is a <em>possible</em> (soft) duplicate of another owner: {@code true} when some
218	     * other owner shares this owner's last name (case-insensitively) and postcode but has a different
219	     * telephone — a near match. Always false for an owner admitted as a declared household member (via
220	     * {@code sharesHousehold}), which is not a suspected duplicate.
221	     * Computed per request, not persisted. See {@link #getPossibleDuplicateOf()} for the matched owner.
222	     */
223	    public Boolean getPossibleDuplicate() {
224	        return this.possibleDuplicate;
225	    }
226	
227	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
228	        this.possibleDuplicate = possibleDuplicate;
229	    }
230	
231	    /**
232	     * The id of the existing owner this owner possibly duplicates (same last name and postcode, different
233	     * telephone), or {@code null} when {@link #getPossibleDuplicate() possibleDuplicate} is false. When
234	     * several owners match, this is the earliest (lowest id). Computed per request, not persisted.
235	     */
236	    public Integer getPossibleDuplicateOf() {
237	        return this.possibleDuplicateOf;
238	    }
239	
240	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
241	        this.possibleDuplicateOf = possibleDuplicateOf;
242	    }
243	
244	    /**
245	     * The owner's membership level, a number from 1 to 3 fixed at creation. Starts at 1; add 1 when an
246	     * email is present; add 1 when {@code namesakeCount} is 0; capped at 3. Level 4 is reserved for
247	     * tenure and is never produced here.
248	     */
249	    public int getMembershipLevel() {
250	        int level = 1;
251	        boolean hasEmail = this.email != null && !this.email.isBlank();
252	        if (hasEmail) {
253	            level++;
254	        }
255	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
256	        if (unique) {
257	            level++;
258	        }
259	        return Math.min(level, 3);
260	    }
261	
262	    /**
263	     * Fixed city-to-region table mapping each known city to its canonical region string.
264	     */
265	    private static final Map<String, String> CITY_REGION = Map.of(
266	        "Sydney", "NSW",
267	        "Melbourne", "VIC",
268	        "Brisbane", "QLD");
269	
270	    /**
271	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
272	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
273	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
274	     */
275	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
276	        "NSW", new int[] {2000, 2099},
277	        "VIC", new int[] {3000, 3099},
278	        "QLD", new int[] {4000, 4099});
279	
280	    /**
281	     * The canonical region for {@code city} derived from the fixed city-to-region table
282	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
283	     * city is not in the table. The single source of truth for the create-time postcode range check in
284	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
285	     */
286	    public static String regionOf(String city) {
287	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
288	    }
289	
290	    /**
291	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
292	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
293	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
294	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
295	     * postcode range check.
296	     */
297	    public static int[] postcodeRangeOf(String region) {
298	        return REGION_POSTCODES.get(region);
299	    }
300	
301	    /**
302	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
303	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
304	     * range.
305	     */
306	    public static String regionOfPostcode(String postcode) {
307	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
308	            return null;
309	        }
310	        int value = Integer.parseInt(postcode);
311	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
312	            int[] range = entry.getValue();
313	            if (value >= range[0] && value <= range[1]) {
314	                return entry.getKey();
315	            }
316	        }
317	        return null;
318	    }
319	
320	    /**
321	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
322	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
323	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
324	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
325	     * customer code is assigned.
326	     */
327	    public String getLocality() {
328	        if (this.customerCode == null) {
329	            return "UNKNOWN";
330	        }
331	        int dash = this.customerCode.indexOf('-');
332	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
333	    }
334	
335	    /**
336	     * The single Luhn check digit (0-9) computed over the digits contained in the
337	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
338	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
339	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
340	     */
341	    public int getCheckDigit() {
342	        String code = this.customerCode;
343	        if (code == null) {
344	            return 0;
345	        }
346	        int sum = 0;
347	        boolean dbl = true;
348	        for (int i = code.length() - 1; i >= 0; i--) {
349	            char c = code.charAt(i);
350	            if (c < '0' || c > '9') {
351	                continue;
352	            }
353	            int d = c - '0';
354	            if (dbl) {
355	                d *= 2;
356	                if (d > 9) {
357	                    d -= 9;
358	                }
359	            }
360	            sum += d;
361	            dbl = !dbl;
362	        }
363	        return (10 - (sum % 10)) % 10;
364	    }
365	
366	    /**
367	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
368	     * {@code "PHONE"}.
369	     */
370	    public String getContactPreference() {
371	        boolean hasEmail = this.email != null && !this.email.isBlank();
372	        return hasEmail ? "EMAIL" : "PHONE";
373	    }
374	
375	    /**
376	     * The single canonical format of an owner's derived identity key:
377	     * {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The telephone and
378	     * household id are used as given (they are expected to already be canonical: E.164 and an assigned
379	     * household id); the email is lower-cased here and a null/blank email, telephone or household id
380	     * contributes an empty component. This is the only place the {@code "|"}-join lives; the stored-owner
381	     * {@link #getIdentityKey()} routes through here so the format cannot drift. The key is a descriptive,
382	     * returned field; create-time duplicate detection itself is keyed on the household alone (see
383	     * {@code CheckHouseholdUnique}).
384	     */
385	    public static String identityKey(String telephone, String email, String householdId) {
386	        String tel = (telephone == null) ? "" : telephone;
387	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
388	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
389	        return tel + "|" + mail + "|" + household;
390	    }
391	
392	    /**
393	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
394	     * household id via {@link #identityKey(String, String, String)}. A descriptive, returned value;
395	     * create-time duplicate detection is keyed on the household (see {@code CheckHouseholdUnique}).
396	     */
397	    public String getIdentityKey() {
398	        return identityKey(this.telephone, this.email, this.householdId);
399	    }
400	
401	    protected Set<Pet> getPetsInternal() {
402	        if (this.pets == null) {
403	            this.pets = new HashSet<>();
404	        }
405	        return this.pets;
406	    }
407	
408	    protected void setPetsInternal(Set<Pet> pets) {
409	        this.pets = pets;
410	    }
411	
412	    public List<Pet> getPets() {
413	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
414	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
415	        return Collections.unmodifiableList(sortedPets);
416	    }
417	
418	    public void setPets(List<Pet> pets) {
419	        this.pets = new HashSet<>(pets);
420	    }
421	
422	    public void addPet(Pet pet) {
423	        getPetsInternal().add(pet);
424	        pet.setOwner(this);
425	    }
426	
427	    /**
428	     * Return the Pet with the given name, or null if none found for this Owner.
429	     *
430	     * @param name to test
431	     * @return true if pet name is already in use
432	     */
433	    public Pet getPet(String name) {
434	        return getPet(name, false);
435	    }
436	
437	    /**
438	     * Return the Pet with the given name, or null if none found for this Owner.
439	     *
440	     * @param name to test
441	     * @return true if pet name is already in use
442	     */
443	    public Pet getPet(String name, boolean ignoreNew) {
444	        name = name.toLowerCase();
445	        for (Pet pet : getPetsInternal()) {
446	            if (!ignoreNew || !pet.isNew()) {
447	                String compName = pet.getName();
448	                compName = compName.toLowerCase();
449	                if (compName.equals(name)) {
450	                    return pet;
451	                }
452	            }
453	        }
454	        return null;
455	    }
456	
457	    public Pet getPet(Integer petId) {
458	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
459	    }
460	
461	    @Override
462	    public String toString() {
463	        return new ToStringCreator(this)
464	
465	            .append("id", this.getId())
466	            .append("new", this.isNew())
467	            .append("lastName", this.getLastName())
468	            .append("firstName", this.getFirstName())
469	            .append("address", this.address)
470	            .append("city", this.city)
471	            .append("telephone", this.telephone)
472	            .toString();
473	    }
474	}
