2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Set;
6	import java.util.regex.Pattern;
7	
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailException;
11	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
12	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
13	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
14	import org.springframework.web.bind.annotation.RequestBody;
15	
16	/**
17	 * Validates a new owner before {@link BuildOwner} runs: every one of firstName, lastName, address,
18	 * city and telephone must be present and non-blank. Any that are missing or blank are collected and
19	 * reported together as a {@link MissingOwnerFieldsException} (a 400), so the body is never persisted.
20	 *
21	 * <p>The telephone is then normalized to E.164 (keep a leading '+' and country code when present,
22	 * otherwise assume '+61' and drop a single leading '0' from the national digits, stripping spaces,
23	 * dashes and brackets and requiring 8 to 15 digits after the '+'); otherwise an
24	 * {@link InvalidTelephoneException} (a 400) is raised. The E.164 value is written back onto the request
25	 * so downstream steps store and return it.
26	 *
27	 * <p>Deliberately does <em>not</em> use {@code @Valid}: bean validation would raise a
28	 * {@code MethodArgumentNotValidException} with a different response shape, whereas this rule must
29	 * answer with an {@code errors} array naming each offending field.
30	 */
31	public class ValidateNewOwner {
32	
33	    /**
34	     * Syntactic email check (the HTML5/Hibernate-Validator {@code @Email} form): a local part of the
35	     * permitted characters, an {@code @}, then a dot-separated domain of label segments. Used only to
36	     * decide between accept and 400; a valid value is then lower-cased and written back onto the request.
37	     */
38	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
39	            "^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?"
40	                    + "(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$");
41	
42	    /**
43	     * Disposable-email providers whose domains are rejected: a syntactically valid address on one of
44	     * these is a 400, so throwaway inboxes cannot be used to register an owner. Lower-cased to compare
45	     * against the canonicalized (lower-cased) email domain.
46	     */
47	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
48	            "mailinator.com", "tempmail.com", "guerrillamail.com");
49	
50	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
51	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
52	            DisposableEmailException {
53	        // This list mirrors OwnerFieldsDto's required fields by hand: it must track the schema's
54	        // `required` set. We check presence/non-blankness only, a narrower rule than the DTO's full
55	        // constraints (@Size/@Pattern), so bean validation is intentionally not used here.
56	        // Normalize the address first so the required-field check rejects an address that is blank
57	        // after normalization (e.g. "   "), and so downstream steps store/return and compare the
58	        // canonical form. OwnerAddress.normalize yields "" for a null or all-whitespace address.
59	        String normalizedAddress = OwnerAddress.normalize(request.getAddress());
60	        request.setAddress(normalizedAddress);
61	
62	        List<String> missing = new ArrayList<>();
63	        require(missing, "firstName", request.getFirstName());
64	        require(missing, "lastName", request.getLastName());
65	        require(missing, "address", normalizedAddress);
66	        require(missing, "city", request.getCity());
67	        require(missing, "telephone", request.getTelephone());
68	        if (!missing.isEmpty()) {
69	            throw new MissingOwnerFieldsException(missing);
70	        }
71	
72	        // Normalize the telephone to E.164. Store the canonical value back so BuildOwner/SaveOwner
73	        // persist it and the response echoes the E.164 form.
74	        String e164 = OwnerTelephone.toE164(request.getTelephone());
75	        if (e164 == null) {
76	            throw new InvalidTelephoneException(request.getTelephone());
77	        }
78	        request.setTelephone(e164);
79	
80	        // Email is optional: only an email that is present (non-blank) must be a valid address. A valid
81	        // value is lower-cased and written back (like telephone above) so downstream steps store and
82	        // return the canonical form.
83	        String email = request.getEmail();
84	        if (email != null && !email.isBlank()) {
85	            if (!EMAIL_PATTERN.matcher(email).matches()) {
86	                throw new InvalidEmailException(email);
87	            }
88	            String canonical = email.toLowerCase();
89	            // Reject throwaway inboxes: a syntactically valid address on a disposable-email domain is a
90	            // 400, so the owner is never persisted. Domain is everything after the last '@'.
91	            String domain = canonical.substring(canonical.lastIndexOf('@') + 1);
92	            if (DISPOSABLE_DOMAINS.contains(domain)) {
93	                throw new DisposableEmailException(email);
94	            }
95	            request.setEmail(canonical);
96	        }
97	
98	        validated.set(request);
99	    }
100	
101	    private static void require(List<String> missing, String field, String value) {
102	        if (value == null || value.isBlank()) {
103	            missing.add(field);
104	        }
105	    }
106	}
